import { readFile, writeFile } from 'node:fs/promises';

// Bundle the target repository templates as text for the Worker (which has no filesystem).
const paths = ['.github/workflows/purge-deleted-image-history.yml', 'scripts/purge-deleted-image-history.sh'];
const files = await Promise.all(paths.map(async path => ({
    path,
    mode: path.endsWith('.sh') ? '100755' : '100644',
    content: await readFile(new URL(`../target-repository/${path}`, import.meta.url), 'utf8'),
})));
await writeFile(new URL('../src/worker/repository-config.generated.ts', import.meta.url),
    '// Generated by scripts/generate-repository-config.mjs; edit target-repository/ instead.\n'
    + `export const repositoryConfigFiles = ${JSON.stringify(files, null, 4)};\n`);
